export function getCsmpStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(CSMP_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
